1	/**
2	 * Scoped per testing.md: this organism's own contract (given a variation + props, does it render
3	 * the right children with the right flags, and does every interactive control still fire its own
4	 * callback) — not ZimmProductCardMedia/ZimmProductCardContent's own internal logic, which is
5	 * already proven in their own index.test.tsx files. Both are composed for real here (not mocked
6	 * out), the same "costs nothing, gives real integration confidence" precedent
7	 * zimmProductCardContent/index.test.tsx already documents for its own composed atoms/molecules.
8	 *
9	 * Only `useMultiStyleConfig` is mocked, with one flat object covering every part every composed
10	 * descendant reads (`ZimmProductCardMedia`, `ZimmSlideIndicator`, `ZimmProductCardContent`,
11	 * `ZimmProductPrice`, `ZimmSizeChipGroup`, `ZimmSizeChip`, and this organism's own `root`) — same
12	 * "neither test setup nor Chakra cares which recipe name asked for it" precedent
13	 * zimmProductCardMedia/index.test.tsx documents. `ZimmProductName`'s `useStyleConfig` call is left
14	 * real/unmocked, same as zimmProductCardContent/index.test.tsx.
15	 */
16	import React from 'react';
17	import { describe, test, expect, vi } from 'vitest';
18	import { render, screen } from '@testing-library/react';
19	import userEvent from '@testing-library/user-event';
20	import { chakra } from '@chakra-ui/react';
21	import { IntlProvider } from 'react-intl';
22	import { MemoryRouter } from 'react-router-dom';
23	import { ZimmProductCard } from './index';
24	import type {
25	  ZimmProductCardProps,
26	  ZimmProductCardImage,
27	  ZimmProductCardBaseProps,
28	  ZimmProductCardPlpVariation,
29	  ZimmProductCardHomeVariation,
30	  ZimmProductCardWishlistVariation,
31	} from './index';
32	import { ZimmProductCard as ZimmProductCardRecipe } from './zimmProductCard.css';
33	// Fix 1 (Scorer rework round 1): needed to compose the REAL close-part style object this
34	// organism's root recipe cascades against — see the "Fix 1" describe block below. `chakra` above
35	// is imported the normal way (not via vi.importActual) because the vi.mock('@chakra-ui/react', ...)
36	// factory below spreads `...actual` and only overrides `useMultiStyleConfig` — `chakra` itself
37	// was never mocked, so this import already resolves to the real Emotion-backed factory.
38	import { ZimmProductCardMedia as ZimmProductCardMediaRecipe } from '../../molecules/zimmProductCardMedia/zimmProductCardMedia.css';
39	// Fix D: the real `breakpoints.md` value, so DESKTOP_QUERY below can't drift from the source
40	// file's own derivation of it. No DOM-level compose-and-read proof for this one (unlike Fix 1/3/
41	// C above) — those all resolve a STATIC declaration; jsdom's actual support for resolving a real
42	// `min-width` media query against getComputedStyle is unreliable enough that the object-shape
43	// assertions below, plus the real-browser check every hover/pointer concern in this file's own
44	// "KNOWN LIMITATION" docblock already defers to, are the honest level of proof here.
45	import { breakpoints } from 'app/theme/foundation';
46	import { CARD_SLOT, HOVER_CAPABLE_QUERY } from '../../zimmProductCardShared';
47	
48	/**
49	 * Fix G's own contribution is a boolean `index.tsx` COMPUTES (`bagHiddenOnMobile`, combining two
50	 * VARIATION_CONFIG fields with `isUnavailable`) before ever calling `useMultiStyleConfig` — the
51	 * "real recipe assertions" pattern used everywhere else in this file proves the RECIPE reacts
52	 * correctly to a given `hideBagOnMobile` value, but says nothing about whether index.tsx computed
53	 * the right value in the first place. `vi.hoisted` lets this mock factory (hoisted above the rest
54	 * of the file by Vitest) share a capture slot with the test body below, without hitting a TDZ
55	 * error from referencing an un-hoisted `let`.
56	 */
57	const { capturedOrganismStyleProps } = vi.hoisted(() => ({
58	  capturedOrganismStyleProps: { current: undefined as Record<string, unknown> | undefined },
59	}));
60	
61	vi.mock('@chakra-ui/react', async (importOriginal) => {
62	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
63	  return {
64	    ...actual,
65	    useMultiStyleConfig: (recipeName: string, props?: Record<string, unknown>) => {
66	      if (recipeName === 'ZimmProductCard') {
67	        capturedOrganismStyleProps.current = props;
68	      }
69	      return {
70	        // This organism's own recipe.
71	        root: {},
72	        // ZimmProductCardMedia.
73	        scrollContainer: {},
74	        slide: {},
75	        image: {},
76	        hoverSwapBase: {},
77	        hoverSwapOverlay: {},
78	        badge: {},
79	        badgeLabel: {},
80	        close: {},
81	        carousel: {},
82	        arrowButton: {},
83	        indicatorWrapper: {},
84	        // ZimmSlideIndicator.
85	        dot: {},
86	        // ZimmProductCardContent.
87	        nameRow: {},
88	        nameLink: {},
89	        bagWrapper: {},
90	        bagButton: {},
91	        attributesRow: {},
92	        colourText: {},
93	        sizeText: {},
94	        priceWrapper: {},
95	        sizeChipWrapper: {},
96	        notifyMeButton: {},
97	        // ZimmProductPrice.
98	        container: {},
99	        wasPrice: {},
100	        nowPrice: {},
101	        // ZimmSizeChipGroup.
102	        radiogroup: {},
103	        oneSize: {},
104	        // ZimmSizeChip.
105	        chip: {},
106	      };
107	    },
108	  };
109	});
110	
111	// ZimmIcon (used by ZimmProductCardContent's bag button) and the icons barrel (used by
112	// ZimmProductCardMedia's close/arrow buttons): known Vitest SVG side-effect issue documented in
113	// .claude/rules/testing.md's "Known gap: ZimmIcon throws under Vitest". Mocked at the same
114	// resolved module each consumer imports — both consumers sit at the same depth below `ui-kits/`
115	// as this test file, so the relative specifiers are identical to what
116	// zimmProductCardContent/index.test.tsx and zimmProductCardMedia/index.test.tsx use themselves.
117	vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
118	vi.mock('../../../icons', () => ({
119	  ChevronLeftIcon: () => null,
120	  ChevronRightIcon: () => null,
121	  CloseIcon: () => null,
122	}));
123	
124	const wrap = (ui: React.ReactElement) =>
125	  render(
126	    <MemoryRouter>
127	      <IntlProvider locale="en" defaultLocale="en">
128	        {ui}
129	      </IntlProvider>
130	    </MemoryRouter>,
131	  );
132	
133	const PRIMARY: ZimmProductCardImage = { src: 'primary.jpg', alt: 'Zimmermann dress, front' };
134	const HOVER: ZimmProductCardImage = { src: 'hover.jpg', alt: 'Zimmermann dress, on model' };
135	const GALLERY: ZimmProductCardImage[] = [
136	  { src: 'g1.jpg', alt: 'Zimmermann dress, front' },
137	  { src: 'g2.jpg', alt: 'Zimmermann dress, side' },
138	  { src: 'g3.jpg', alt: 'Zimmermann dress, back' },
139	];
140	
141	const SIZES = [
142	  { value: 'xs', label: 'XS' },
143	  { value: 's', label: 'S' },
144	];
145	
146	/**
147	 * Module-scope (not describe-block-local) so both the "real recipe assertions" describe block
148	 * below AND the Fix 1 / Fix 2 (Scorer rework round 1) DOM-level proof blocks further down can
149	 * share one definition rather than each hand-duplicating the same literal selector strings.
150	 */
151	const STRETCH_KEY = `[data-card-slot="${CARD_SLOT.content}"] a::after`;
152	const CLOSE_LIFT_KEY = `[data-card-slot="${CARD_SLOT.close}"]`;
153	const CAROUSEL_LIFT_KEY = `[data-card-slot="${CARD_SLOT.carousel}"]`;
154	const CONTENT_LIFT_KEY = `[data-card-slot="${CARD_SLOT.content}"] button`;
155	const PRICE_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.price}"]`;
156	const SIZE_CHIPS_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.sizeChips}"]`;
157	const HOVER_PRICE_KEY = `&:hover ${PRICE_KEY}`;
158	const HOVER_SIZE_CHIPS_KEY = `&:hover ${SIZE_CHIPS_KEY}`;
159	// Fix 2 (Scorer rework round 1): the keyboard-reachable equivalent of each hover-reveal rule
160	// above — see this file's own docblock note on the compound-selector vs separate-key idiom
161	// question, resolved by reading zimmSearchInput.css.ts and globalStyles.ts's zimmFormRow/
162	// zimmFormRowInverse: both use a separate sibling key (`_focusWithin` alongside `_hover`), never
163	// a comma-joined compound selector. This file already uses raw selector strings (not Chakra's
164	// `_hover`/`_focusWithin` shorthand props) because the hover rules need a descendant-combinator
165	// path baked into the selector itself, so the equivalent here is a separate `'&:focus-within ...'`
166	// string key alongside the existing `'&:hover ...'` key, not a merged `'&:hover, &:focus-within ...'`
167	// selector.
168	const FOCUS_WITHIN_PRICE_KEY = `&:focus-within ${PRICE_KEY}`;
169	const FOCUS_WITHIN_SIZE_CHIPS_KEY = `&:focus-within ${SIZE_CHIPS_KEY}`;
170	// Fix C: notify-me's own reveal-key trio, all three living INSIDE the HOVER_CAPABLE_QUERY block
171	// (see zimmProductCard.css.ts docblock point 4 for why this is the opposite structure from price/
172	// size-chips above — the "hidden by default" half must not be reachable by a touch pointer).
173	const NOTIFY_ME_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.notifyMe}"]`;
174	const HOVER_NOTIFY_ME_KEY = `&:hover ${NOTIFY_ME_KEY}`;
175	const FOCUS_WITHIN_NOTIFY_ME_KEY = `&:focus-within ${NOTIFY_ME_KEY}`;
176	// Fix D: the PLP-only bag-icon mobile hide — a viewport-width gate, not a hover one (see
177	// zimmProductCard.css.ts docblock point 5). Built from the real `breakpoints` import (not a
178	// hand-typed literal) so this can't silently drift from what the source file actually emits —
179	// `breakpoints.md` is `'48em'`, not a `768px` string, despite that being its px-equivalent value.
180	const DESKTOP_QUERY = `@media (min-width: ${breakpoints.md})`;
181	const BAG_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.bag}"]`;
182	
183	/** Mocks the scroll container's native `scrollTo` (absent under jsdom), same technique as
184	 *  zimmProductCardMedia/index.test.tsx's own mockScrollTo. */
185	const mockScrollTo = (): ReturnType<typeof vi.fn> => {
186	  const scrollContainer = screen.getByTestId('card-media-scroll');
187	  const scrollTo = vi.fn();
188	  scrollContainer.scrollTo = scrollTo;
189	  return scrollTo;
190	};
191	
192	/**
193	 * A complete, valid props object for a given variation — narrows on `variation` with a plain
194	 * `switch` (fine here: the "no switch/if on props.variation" constraint applies only to
195	 * index.tsx's own render body, not to test fixtures).
196	 *
197	 * Overloaded (not a single `(variation) => ZimmProductCardProps` signature) so a call site that
198	 * passes a literal (`buildCardProps('plp')`) gets back the properly *narrow* per-variation type,
199	 * not the full union — needed so a test can then add a variation-specific prop on top (e.g.
200	 * `{...buildCardProps('wishlist')} onRemove={fn}`) without TypeScript rejecting it as "not
201	 * present on every union member." A `test.each` call site passing a runtime (non-literal)
202	 * `variation` still resolves to the final, general overload below.
203	 */
204	function buildCardProps(variation: 'plp'): ZimmProductCardBaseProps & ZimmProductCardPlpVariation;
205	function buildCardProps(variation: 'home'): ZimmProductCardBaseProps & ZimmProductCardHomeVariation;
206	function buildCardProps(variation: 'wishlist'): ZimmProductCardBaseProps & ZimmProductCardWishlistVariation;
207	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps;
208	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps {
209	  const base = {
210	    id: 'p1',
211	    href: '/product/1',
212	    name: 'Natura Dress',
213	    headingLevel: 'h3' as const,
214	    primaryImage: PRIMARY,
215	  };
216	  switch (variation) {
217	    case 'wishlist':
218	      return { ...base, variation, colour: 'Ivory', size: 'M', onRemove: vi.fn() };
219	    case 'home':
220	      return { ...base, variation };
221	    case 'plp':
222	      return { ...base, variation };
223	    default:
224	      // Exhaustiveness guard — a new union member without a matching branch here fails `tsc`,
225	      // not silently falls through to a wrong variation's shape.
226	      return ((): never => {
227	        throw new Error(`buildCardProps: unhandled variation ${JSON.stringify(variation)}`);
228	      })();
229	  }
230	}
231	
232	describe('ZimmProductCardProps — discriminated union is enforced at compile time', () => {
233	  // Both cases below are type-only proof: `@ts-expect-error` makes `tsc --noEmit` fail this file
234	  // if the offending line does NOT produce a compile error (an "Unused '@ts-expect-error'
235	  // directive" diagnostic) — so these only stay green while the union genuinely rejects the
236	  // invalid shape. The runtime assertion is trivial; TypeScript strips the annotation either way,
237	  // so the object still constructs and runs at test time regardless of what `tsc` says about it.
238	  test('wishlist variation requires onRemove, colour and size (type-only)', () => {
239	    // @ts-expect-error — wishlist requires onRemove, colour and size; none are supplied here.
240	    const invalid: ZimmProductCardProps = {
241	      id: 'p1',
242	      href: '/product/1',
243	      name: 'Dress',
244	      headingLevel: 'h3',
245	      primaryImage: PRIMARY,
246	      variation: 'wishlist',
247	    };
248	    expect(invalid).toBeDefined();
249	  });
250	
251	  test('home variation does not accept onRemove (type-only)', () => {
252	    // Assigned to the narrow per-variation intersection, not the `ZimmProductCardProps` union
253	    // alias: TypeScript's excess-property check on a *union* target only flags a property as
254	    // excess when it is unknown to EVERY member, so `onRemove` (valid on the wishlist member)
255	    // would silently pass here even under `variation: 'home'` if assigned to the union type
256	    // directly — confirmed empirically while building this test (an earlier version of this
257	    // exact case, assigned to `ZimmProductCardProps`, produced an "unused @ts-expect-error"
258	    // compile error because of this). The narrow intersection has no such escape hatch: it is a
259	    // plain object type with no `onRemove` key anywhere, so the excess property is genuinely
260	    // unknown and TypeScript reports it.
261	    //
262	    // The directive sits directly above the `onRemove` line, not the `const invalid = {` line
263	    // above it: TS anchors this specific "object literal may only specify known properties"
264	    // diagnostic to the offending property's own line, and `@ts-expect-error` only suppresses
265	    // (and only counts as "used" for) a diagnostic reported on the *immediate next* line.
266	    const invalid: ZimmProductCardBaseProps & ZimmProductCardHomeVariation = {
267	      id: 'p2',
268	      href: '/product/1',
269	      name: 'Dress',
270	      headingLevel: 'h3',
271	      primaryImage: PRIMARY,
272	      variation: 'home',
273	      // @ts-expect-error — onRemove does not exist on the home variation's own shape.
274	      onRemove: () => {},
275	    };
276	    expect(invalid).toBeDefined();
277	  });
278	});
279	
280	describe('ZimmProductCard — AC1: primary image renders for every variation x availability', () => {
281	  const cases: Array<[ZimmProductCardProps['variation'], boolean]> = [
282	    ['plp', false],
283	    ['plp', true],
284	    ['home', false],
285	    ['home', true],
286	    ['wishlist', false],
287	    ['wishlist', true],
288	  ];
289	
290	  test.each(cases)('variation=%s, isUnavailable=%s renders the primary image', (variation, isUnavailable) => {
291	    wrap(<ZimmProductCard {...buildCardProps(variation)} isUnavailable={isUnavailable} />);
292	    const img = screen.getByRole('img', { name: PRIMARY.alt });
293	    expect(img).toHaveAttribute('src', PRIMARY.src);
294	  });
295	});
296	
297	describe('ZimmProductCard — exactly one real anchor regardless of variation', () => {
298	  test.each(['plp', 'home', 'wishlist'] as const)('variation=%s renders exactly one <a>', (variation) => {
299	    wrap(<ZimmProductCard {...buildCardProps(variation)} />);
300	    const links = screen.getAllByRole('link');
301	    expect(links).toHaveLength(1);
302	    expect(links[0]).toHaveAttribute('href', '/product/1');
303	  });
304	});
305	
306	/**
307	 * KNOWN LIMITATION — read before trusting these as proof of the real z-index layering.
308	 *
309	 * Every test below fires a click/keydown directly on the target control's own DOM node via
310	 * Testing Library. That proves the CALLBACK WIRING is correct: the right element calls the right
311	 * handler when it is actually interacted with. It does NOT prove that a real mouse click at that
312	 * screen position, in an actual browser, would land on that control rather than on the invisible
313	 * stretched-link `::after` overlay sitting over the whole card — jsdom performs no real layout,
314	 * paint, or hit-testing (no CSS cascade resolution, no stacking-context/z-index comparison, no
315	 * geometry at all); `fireEvent`/`user-event` dispatch straight to the node you name, bypassing
316	 * whatever a browser's hit-testing algorithm would actually resolve at that (x, y). The
317	 * `zimmProductCard.css.ts` recipe assertions further below prove the CSS this organism emits has
318	 * the right `position`/`z-index` values (verified by literally compiling it through this
319	 * project's real Stylis — see that describe block) — but going from "the right CSS values exist"
320	 * to "a real browser click lands on the right element" is exactly the gap a real-browser
321	 * (Playwright or manual) check is for. Treat this whole file as necessary, not sufficient, proof.
322	 */
323	describe('ZimmProductCard — every interactive control stays separately clickable (wiring only, see limitation above)', () => {
324	  test('the bag button fires onAddToBag independently of the name-link overlay (PLP)', async () => {
325	    const onAddToBag = vi.fn();
326	    const user = userEvent.setup();
327	    wrap(<ZimmProductCard {...buildCardProps('plp')} onAddToBag={onAddToBag} />);
328	    await user.click(screen.getByRole('button', { name: 'Add to bag' }));
329	    expect(onAddToBag).toHaveBeenCalledTimes(1);
330	  });
331	
332	  test('the carousel arrows fire independently of the name-link overlay when there is more than one image', async () => {
333	    const user = userEvent.setup();
334	    wrap(<ZimmProductCard {...buildCardProps('plp')} images={GALLERY} />);
335	    mockScrollTo();
336	    await user.click(screen.getByRole('button', { name: 'Next image' }));
337	    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
338	  });
339	
340	  test('a size chip fires onSizeChipSelect independently of the name-link overlay (PLP)', async () => {
341	    const onSizeChipSelect = vi.fn();
342	    const user = userEvent.setup();
343	    wrap(<ZimmProductCard {...buildCardProps('plp')} sizeChipValues={SIZES} onSizeChipSelect={onSizeChipSelect} />);
344	    await user.click(screen.getByRole('radio', { name: 'S' }));
345	    expect(onSizeChipSelect).toHaveBeenCalledWith('s');
346	  });
347	
348	  test('the remove (close) button fires onRemove independently of the name-link overlay (Wishlist)', async () => {
349	    const onRemove = vi.fn();
350	    const user = userEvent.setup();
351	    wrap(<ZimmProductCard {...buildCardProps('wishlist')} onRemove={onRemove} />);
352	    const button = screen.getByRole('button', { name: 'Remove Natura Dress from wishlist' });
353	    await user.click(button);
354	    expect(onRemove).toHaveBeenCalledTimes(1);
355	  });
356	
357	  test('the bag button also fires onAddToBag on a Wishlist card, independently of the remove button', async () => {
358	    const onAddToBag = vi.fn();
359	    const user = userEvent.setup();
360	    wrap(<ZimmProductCard {...buildCardProps('wishlist')} onAddToBag={onAddToBag} />);
361	    await user.click(screen.getByRole('button', { name: 'Add to bag' }));
362	    expect(onAddToBag).toHaveBeenCalledTimes(1);
363	  });
364	
365	  test('the name link itself is still a real, working anchor to href, not swallowed by its own overlay', () => {
366	    wrap(<ZimmProductCard {...buildCardProps('plp')} />);
367	    expect(screen.getByRole('link', { name: 'Natura Dress' })).toHaveAttribute('href', '/product/1');
368	  });
369	});
370	
371	describe('ZimmProductCard — VARIATION_CONFIG drives composed-child props (a sample, not exhaustive — full matrix is Media/Content’s own test responsibility)', () => {
372	  test('home never renders the bag, attributes row or size chips', () => {
373	    wrap(<ZimmProductCard {...buildCardProps('home')} currentPrice="$100.00" />);
374	    expect(screen.queryByRole('button', { name: 'Add to bag' })).not.toBeInTheDocument();
375	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`)).not.toBeInTheDocument();
376	  });
377	
378	  test('wishlist renders the colour/size attributes row', () => {
379	    wrap(<ZimmProductCard {...buildCardProps('wishlist')} currentPrice="$100.00" />);
380	    expect(screen.getByTestId('card-content-attributes')).toBeInTheDocument();
381	  });
382	
383	  test('plp out-of-stock renders a disabled bag and a notify-me CTA', () => {
384	    const onNotifyMe = vi.fn();
385	    wrap(<ZimmProductCard {...buildCardProps('plp')} isUnavailable onNotifyMe={onNotifyMe} />);
386	    expect(screen.getByRole('button', { name: 'Add to bag' })).toBeDisabled();
387	    // Fix C: the organism's own recipe hover-gates this button via `[data-card-slot="notifyMe"]`
388	    // (see zimmProductCard.css.ts docblock point 4) — needs the real attribute present on the
389	    // real composed tree, not just Content's own isolated test coverage of the same element.
390	    expect(screen.getByRole('button', { name: 'Notify me' })).toHaveAttribute('data-card-slot', 'notifyMe');
391	  });
392	
393	  /**
394	   * Fix G (full-sweep follow-up visual audit): `bagHiddenOnMobile` is computed in index.tsx from
395	   * TWO VARIATION_CONFIG fields (`hideBagOnMobile` — PLP's unconditional rule — and
396	   * `hideBagOnMobileWhenUnavailable` — Wishlist's narrower, stock-status-dependent one) plus
397	   * `isUnavailable`. Reading it back off `capturedOrganismStyleProps` (populated by this file's
398	   * own `useMultiStyleConfig` mock — see that mock's own comment) is what actually proves index.tsx
399	   * combined them correctly; the "real recipe assertions" block below only proves the RECIPE
400	   * reacts correctly to whatever `hideBagOnMobile` value it's handed, not that index.tsx computed
401	   * the right one for a given variation x availability combination.
402	   */
403	  test.each([
404	    ['plp', false, true],
405	    ['plp', true, true],
406	    ['wishlist', false, false],
407	    ['wishlist', true, true],
408	    ['home', false, false],
409	    ['home', true, false],
410	  ] as const)(
411	    'variation=%s, isUnavailable=%s -> hideBagOnMobile=%s passed to the recipe',
412	    (variation, isUnavailable, expected) => {
413	      wrap(<ZimmProductCard {...buildCardProps(variation)} isUnavailable={isUnavailable} onNotifyMe={vi.fn()} />);
414	      expect(capturedOrganismStyleProps.current?.hideBagOnMobile).toBe(expected);
415	    },
416	  );
417	
418	  /**
419	   * Same capture technique, closing the loop on Fix C's own suppression logic
420	   * (`hoverHidesPrice`/`hoverRevealsSizeSelector` AND-ed with `!isUnavailable`,
421	   * `sizeSelectorUnavailable` AND-ed with `isUnavailable`) — previously only ever verified at the
422	   * recipe-reaction level (a manually-constructed input into `ZimmProductCardRecipe.baseStyle`
423	   * directly), never proven that index.tsx itself computes that input correctly for a real
424	   * variation x availability combination.
425	   */
426	  test.each([
427	    ['home', false, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: false }],
428	    ['home', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: false }],
429	    ['plp', false, { hoverHidesPrice: true, hoverRevealsSizeSelector: true, sizeSelectorUnavailable: false }],
430	    ['plp', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: true }],
431	    ['wishlist', false, { hoverHidesPrice: true, hoverRevealsSizeSelector: true, sizeSelectorUnavailable: false }],
432	    ['wishlist', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: true }],
433	  ] as const)(
434	    'variation=%s, isUnavailable=%s -> the unavailable-suppression trio resolves to %o',
435	    (variation, isUnavailable, expected) => {
