 * no per-story Figma node citation, shorter docblocks, and — per Marcel's own recent decision — no
 * shared fixtures import (see the local consts above). Every AC gets its own independently
 * clickable, independently named sidebar entry; none are folded, merged, or aliased, including the
 * 5 "Recently Viewed Full History" stories, which reuse PLP's own `variation:'plp'` code path
 * (there is no dedicated Recently Viewed variation — see `../index.tsx`'s own module docblock) but
 * are still written out as 5 separate exports, not re-exported aliases of the PLP ones.
 *
 * Conventions copied from `../nodeCoverage/index.stories.tsx` (matched exactly, not reinvented):
 * the same `Meta`/`StoryObj` typing, the same `MemoryRouter`-only meta-level decorator with a
 * per-story `widthDecorator(width)` for stories that need a fixed card width, and the same
 * `LiveSizeSelectionCard` wrapper (itself copied from that file, which itself copied it from
 * `../index.stories.tsx`'s original `DefaultExample` — an accepted, deliberate three-way
 * duplication at this point, not a new one) for every `plp`/`wishlist`-variation story below, so a
 * real click on a revealed size chip visibly selects instead of silently no-op'ing against a
 * static `fn()` spy.
 *
 * KNOWN LIMITATION (the three mobile stories — PLP_AC4, Home_AC4, RecentlyViewed_AC4): carried
 * forward from `../nodeCoverage/index.stories.tsx`'s own note, plus one addition found while
 * writing this file. That file already documents that `hideBagOnMobile` / the unavailable-mobile
 * price swap (Fix D/F/G) are real `@media (min-width: 48em)` **viewport** queries — a narrow
 * decorator `Box` cannot trigger them, only the real browser window's own width does. The
 * size-selector / price hover-reveal PLP_AC4 and Home_AC4 below touch is gated by a *different*
 * query, `HOVER_CAPABLE_QUERY` (`@media (hover: hover) and (pointer: fine)`,
 * `../../../zimmProductCardShared.ts`) — a pointer-CAPABILITY query, not a width one. That query
 * matches Marcel's own desktop/laptop browser (mouse or trackpad) regardless of how narrow any
 * element on the page is, including this decorator `Box` — and, unlike the viewport-width case,
 * regardless of how narrow the real browser WINDOW is too. A genuine mouse hover over either story
 * below will therefore still trigger the normal desktop hover-reveal (size chips / price
 * appearing) even though the card is drawn at the 179px mobile width — the true "no hover at all"
 * mobile experience these two ACs describe can only be produced by an actual touchscreen or by
 * your browser's own device-emulation mode (which fakes `hover: none`), not by narrowing anything
 * in Storybook. Flagged again in both stories' own doc comments below, not just here.
 */
const meta: Meta<typeof ZimmProductCard> = {
  title: 'Commerce/ZimmProductCard/AC Coverage',
  component: ZimmProductCard,
  parameters: { layout: 'padded' },
  decorators: [
    (StoryFn) => (
      <MemoryRouter>
        <StoryFn />
      </MemoryRouter>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmProductCard>;

/**
 * Copied verbatim from `../nodeCoverage/index.stories.tsx` (see that file's own docblock for the
 * full rationale — it documents this exact wrapper). Every `plp`/`wishlist` story below renders
 * through this wrapper so a clicked size chip visibly selects instead of silently doing nothing
 * against a static arg.
 */
const LiveSizeSelectionCard = (args: ZimmProductCardProps) => {
  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(() =>
    args.variation === 'plp' || args.variation === 'wishlist' ? args.selectedSizeChipValue : undefined,
  );
  const isSizeChipVariation = args.variation === 'plp' || args.variation === 'wishlist';
  const onSizeChipSelectFromArgs = isSizeChipVariation ? args.onSizeChipSelect : undefined;
  const handleSizeChipSelect = (value: string) => {
    setSelectedSizeChipValue(value);
    onSizeChipSelectFromArgs?.(value);
  };
  const propsWithLiveSelection: ZimmProductCardProps = isSizeChipVariation
    ? { ...args, selectedSizeChipValue, onSizeChipSelect: handleSizeChipSelect }
    : args;
  return <ZimmProductCard {...propsWithLiveSelection} />;
};

const widthDecorator = (width: string) => [
  (StoryFn: () => React.ReactElement) => (
    <Box width={width}>
      <StoryFn />
    </Box>
  ),
];

// Base args per Type — same fixture product as `../index.stories.tsx` and `../nodeCoverage`'s own
// HOME_BASE/PLP_BASE/WISHLIST_BASE, so every ZimmProductCard story across the whole component
// family reads as the same consistent fixture product. Each story below spreads one of these and
// overrides only what that specific AC needs.
const HOME_BASE: ZimmProductCardProps = {
  id: 'ac-home-base',
  variation: 'home',
  name: 'Natura Long Sleeve Linen Mini Dress',
  headingLevel: 'h3',
  href: '/product/123',
  primaryImage: PRIMARY_IMAGE,
  hoverImage: HOVER_IMAGE,
  currentPrice: '$595.00',
  badge: 'Runway',
};

const PLP_BASE: ZimmProductCardProps = {
  id: 'ac-plp-base',
  variation: 'plp',
  name: 'Natura Long Sleeve Linen Mini Dress',
  headingLevel: 'h3',
  href: '/product/123',
  primaryImage: PRIMARY_IMAGE,
  hoverImage: HOVER_IMAGE,
  currentPrice: '$595.00',
  badge: 'Runway',
  onAddToBag: fn(),
  sizeChipValues: SIZES,
  onSizeChipSelect: fn(),
};

const WISHLIST_BASE: ZimmProductCardProps = {
  id: 'ac-wishlist-base',
  variation: 'wishlist',
  name: 'Natura Long Sleeve Linen Mini Dress',
  headingLevel: 'h3',
  href: '/product/123',
  primaryImage: PRIMARY_IMAGE,
  hoverImage: HOVER_IMAGE,
  currentPrice: '$595.00',
  badge: 'Runway',
  colour: 'Ivory',
  size: 'M',
  onRemove: fn(),
  onAddToBag: fn(),
  sizeChipValues: SIZES,
  selectedSizeChipValue: 'm',
  onSizeChipSelect: fn(),
};

/**
 * Shared three-card composition for `Core_AC1` (primary image always renders, regardless of
 * variation) and `Extensibility_AC1` (a visual anchor only — its real proof is cited in that
 * story's own doc comment, not this render). Each card uses its own variation's minimal/default
 * base fixture with only `id` overridden, computed ahead of the JSX (not spread inline with a
 * trailing prop) so each stays a single, fully-typed `ZimmProductCardProps` value — matching how
 * every story's own `args` field below is built.
 */
const renderThreeVariations = () => {
  const home: ZimmProductCardProps = { ...HOME_BASE, id: 'ac-three-variations-home' };
  const plp: ZimmProductCardProps = { ...PLP_BASE, id: 'ac-three-variations-plp' };
  const wishlist: ZimmProductCardProps = { ...WISHLIST_BASE, id: 'ac-three-variations-wishlist' };
  return (
    <Box display="flex" flexWrap="wrap" gap="24px">
      <Box width="288px">
        <ZimmProductCard {...home} />
      </Box>
      <Box width="288px">
        <ZimmProductCard {...plp} />
      </Box>
      <Box width="288px">
        <ZimmProductCard {...wishlist} />
      </Box>
    </Box>
  );
};

// ---------------------------------------------------------------------------------------------
// Core (2)

/**
 * "primary product image is always displayed regardless of variation."
 *
 * Home, PLP and Wishlist rendered side by side, each with its own minimal/default props — look
 * for the same primary image (the dark placeholder swatch) present in all three cards at a
 * glance. No interaction needed.
 */
export const Core_AC1: Story = {
  name: 'Core AC1 — "primary product image is always displayed regardless of variation"',
  render: renderThreeVariations,
};

/**
 * "renders correctly without page-specific logic embedded in the component itself."
 *
 * A single plain PLP card, no special setup beyond this file's own standard (288px) decorator.
 * Nothing to click or hover for this one — the component takes only props (no data-fetching hook,
 * no page import); the fact it renders correctly here, with zero page context beyond the router
 * this file's own meta-level decorator supplies for the internal `Link`, is itself the
 * demonstration.
 */
export const Core_AC2: Story = {
  name: 'Core AC2 — "renders correctly without page-specific logic embedded in the component itself"',
  decorators: widthDecorator('288px'),
  args: { ...PLP_BASE, id: 'ac-core-ac2' },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

// ---------------------------------------------------------------------------------------------
// PLP (5)

/**
 * PLP AC1 — "default state: image, name, badge, price, cart icon visible."
 *
 * No hover needed — everything this AC lists is visible immediately at rest.
 */
export const PLP_AC1: Story = {
  name: 'PLP AC1 — default state: image, name, badge, price, cart icon visible',
  decorators: widthDecorator('288px'),
  args: { ...PLP_BASE, id: 'ac-plp-ac1' },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * PLP AC2 — "hover: size selector visible, price disappears, image switches to model photo."
 *
 * Hover the card to check all three happen together: the price is replaced by the size-chip
 * picker (click a chip — it visibly selects, this story is genuinely interactive, not a frozen
 * frame), and the image crossfades to the on-model hover photo.
 */
export const PLP_AC2: Story = {
  name: 'PLP AC2 — hover: size selector visible, price disappears, image switches to model photo',
  decorators: widthDecorator('288px'),
  args: { ...PLP_BASE, id: 'ac-plp-ac2' },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * PLP AC3 — "hover: arrows appear."
 *
 * `images` is set to a 3-image gallery so there's something for the arrows to page through. Hover
 * to check the prev/next arrows appear (the price/size-selector swap from PLP AC2 also fires at
 * the same time on this card — that's expected, both are driven by the same hover state).
 */
export const PLP_AC3: Story = {
  name: 'PLP AC3 — hover: arrows appear',
  decorators: widthDecorator('288px'),
  args: { ...PLP_BASE, id: 'ac-plp-ac3', hoverImage: undefined, images: GALLERY_IMAGES },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * PLP AC4 — "mobile: size selector not displayed."
 *
 * Rendered at the 179px mobile card width. Confirm no size-chip UI appears anywhere, including if
 * you try clicking/hovering.
 *
 * HONEST CAVEAT (see this file's own top-of-file KNOWN LIMITATION note): the size-selector
 * hover-reveal is gated by pointer capability (`hover: hover; pointer: fine`), not by this
 * decorator's width. Your desktop/laptop browser matches that query regardless of how narrow this
 * Box is, so a genuine mouse hover here WILL still reveal the size-chip picker — the same as any
 * desktop PLP card. To see the true "never shown" mobile behaviour, don't hover at all (the at-rest
 * render correctly shows no size-chip UI, matching this AC), or use your browser's own
 * device-emulation mode.
 */
export const PLP_AC4: Story = {
  name: 'PLP AC4 — mobile: size selector not displayed',
  decorators: widthDecorator('179px'),
  args: { ...PLP_BASE, id: 'ac-plp-ac4' },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * PLP AC5 — "out of stock: cart greyed out, notify-me appears on hover instead of price."
 *
 * `isUnavailable: true`, `onNotifyMe` set. Hover to check the bag renders disabled and "Notify me"
 * appears.
 *
 * HONEST NOTE (flagged to Marcel separately, not softened here): on desktop this is currently
 * ADDITIVE, not a literal swap — the price stays visible and "Notify me" simply joins it on hover,
 * rather than replacing it. That matches the shipped design (see `../index.tsx`'s own module
 * docblock and `../index.stories.tsx`'s `PLPOutOfStock` story), not this AC's literal wording.
 */
export const PLP_AC5: Story = {
  name: 'PLP AC5 — out of stock: cart greyed out, notify-me appears on hover instead of price',
  decorators: widthDecorator('288px'),
  args: { ...PLP_BASE, id: 'ac-plp-ac5', isUnavailable: true, onNotifyMe: fn() },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

// ---------------------------------------------------------------------------------------------
// Home (4)

/**
 * Home AC1 — "default: image and name only."
 *
 * At rest, only the image and name render. `HOME_BASE` also carries `badge`/`hoverImage` —
 * deliberately: Home suppresses both (`VARIATION_CONFIG.showBadge`/`showHoverImageSwap` are both
 * false in `../index.tsx`), so their presence here without ever appearing on screen is itself part
 * of the proof, not an oversight.
 */
export const Home_AC1: Story = {
  name: 'Home AC1 — default: image and name only',
  decorators: widthDecorator('288px'),
  args: { ...HOME_BASE, id: 'ac-home-ac1' },
};

/**
 * Home AC2 — "hover: arrows appear."
 *
 * `images` is set to a 3-image gallery. Hover to check the prev/next arrows appear (price also
 * appears at the same time on this card — that's Home AC3, driven by the same hover state).
 */
export const Home_AC2: Story = {
  name: 'Home AC2 — hover: arrows appear',
  decorators: widthDecorator('288px'),
  args: { ...HOME_BASE, id: 'ac-home-ac2', images: GALLERY_IMAGES },
};

/**
 * Home AC3 — "hover: price appears."
 *
 * `currentPrice` is set. Hover the card to check the price appears — Home is the one variation
 * where price is hidden until hover rather than visible by default.
 */
export const Home_AC3: Story = {
  name: 'Home AC3 — hover: price appears',
  decorators: widthDecorator('288px'),
  args: { ...HOME_BASE, id: 'ac-home-ac3' },
};

/**
 * Home AC4 — "mobile: user only sees image and name."
 *
 * Rendered at the 179px mobile card width, as-is — the real shipped behaviour, not a hypothetical
 * "what the AC says" mockup.
 *
 * HONEST NOTE (stated plainly, not hidden): the actual shipped behaviour ALSO shows price on
 * mobile — it matches Figma, but contradicts this AC's literal text. See `../index.tsx`'s own
 * module docblock ("Home ... Mobile ... shows price unconditionally instead") and
 * `../index.stories.tsx`'s `Home` story (Fix E) for the confirmed reasoning: Mobile has no Hover
 * variant at all, so a price hidden "by default, shown on hover" would never be shown there at
 * all.
 *
 * HONEST CAVEAT on top of that (see this file's own top-of-file KNOWN LIMITATION note): that real
 * mobile behaviour only actually happens on a device with no hover capability at all (a real
 * touchscreen, or your browser's device-emulation mode). In THIS desktop Storybook session, at
 * rest (not hovered), you will see exactly what this AC's literal text describes — image and name
 * only, price hidden — because your browser DOES match the hover-capable query this card's
 * price-reveal is gated by, regardless of this decorator's narrow width; hovering it will reveal
 * price exactly like a normal desktop Home card would. Neither observation is a bug: they're two
 * different, correct halves of the same conditional CSS, and this desktop-bound Storybook session
 * can only easily show you one of them at a time.
 */
export const Home_AC4: Story = {
  name: 'Home AC4 — mobile: user only sees image and name',
  decorators: widthDecorator('179px'),
  args: { ...HOME_BASE, id: 'ac-home-ac4' },
};

// ---------------------------------------------------------------------------------------------
// Wishlist (4)

/**
 * Wishlist AC1 — "default: image, cart icon, name, colour, size, badge, price."
 *
 * `colour`/`size`/`badge` all set. No hover needed — everything this AC lists is visible
 * immediately at rest.
 */
