  name: 'Wishlist AC1 — default: image, cart icon, name, colour, size, badge, price',
  decorators: widthDecorator('288px'),
  args: { ...WISHLIST_BASE, id: 'ac-wishlist-ac1' },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * Wishlist AC2 — 'remove ("x") CTA top right.'
 *
 * Same setup as Wishlist AC1. Look at the top-right corner of the image for the close/remove
 * ("x") overlay button.
 */
