 * ticket's own ACs. Same HONEST CAVEAT as PLP AC4 applies here too: a genuine mouse hover in this
 * desktop Storybook session will still reveal the size-chip picker regardless of this decorator's
 * mobile width — see this file's own top-of-file KNOWN LIMITATION note and PLP AC4's own doc
 * comment above.
 */
export const RecentlyViewed_AC4: Story = {
  name: 'Recently Viewed AC4 — mobile: size selector not displayed',
  decorators: widthDecorator('179px'),
  args: { ...PLP_BASE, id: 'ac-recently-viewed-ac4' },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * Recently Viewed AC5 — same as PLP AC5: "out of stock: cart greyed out, notify-me appears on
 * hover instead of price." Same code path as PLP AC5 — this variation has no dedicated code,
 * `variation:'plp'` is used for it per the ticket's own ACs. Same honest additive-not-swap note as
 * PLP AC5 applies here too — see that story's own doc comment above.
 */
export const RecentlyViewed_AC5: Story = {
  name: 'Recently Viewed AC5 — out of stock: cart greyed out, notify-me appears on hover instead of price',
  decorators: widthDecorator('288px'),
  args: { ...PLP_BASE, id: 'ac-recently-viewed-ac5', isUnavailable: true, onNotifyMe: fn() },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

// ---------------------------------------------------------------------------------------------
// Extensibility (1)

/**
 * "a new style can be configured without restructuring the base component."
 *
 * Not a visual AC — this render (reusing Core AC1's own three-card composition) exists only so
 * there's something on screen to look at. The real proof is in the cited code, not this render:
 *   - `VARIATION_CONFIG` in `../index.tsx` is a plain data table keyed by variation; the render
 *     body contains zero `switch`/`if` on `props.variation` — verified this session via
 *     `grep -n 'variation ===\|switch (variation)' index.tsx`, which matches only that file's own
 *     docblock line quoting the command itself, not any real branching.
 *   - The two `@ts-expect-error` compile-time cases in `../index.test.tsx`
 *     ("wishlist variation requires onRemove, colour and size" and "home variation does not accept
 *     onRemove") prove the discriminated-union type itself enforces per-variation field
